std::wstring pipeName(const std::wstring&suffix){HANDLE token=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))return {};DWORD n=0;GetTokenInformation(token,TokenUser,nullptr,0,&n);std::string storage(n,'\0');if(!GetTokenInformation(token,TokenUser,storage.data(),n,&n)){CloseHandle(token);return {};}CloseHandle(token);LPWSTR sid=nullptr;if(!ConvertSidToStringSidW(reinterpret_cast<TOKEN_USER*>(storage.data())->User.Sid,&sid))return {};DWORD session=0;ProcessIdToSessionId(GetCurrentProcessId(),&session);std::wstring name=L"\\\\.\\pipe\\LingheInput.Activity."+std::wstring(sid)+L"."+std::to_wstring(session);LocalFree(sid);if(suffix.size()>96||suffix.find_first_not_of(L"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-.")!=std::wstring::npos)return {};return suffix.empty()?name:name+L"."+suffix;}
std::wstring gateName(const std::wstring&suffix){auto name=pipeName(suffix);return name.empty()?L"":L"Local\\"+name.substr(9)+L".gate";}
std::wstring contextCapabilityName(const std::wstring&suffix){return gateName(suffix)+L".context-v2";}
std::wstring learningName(const std::wstring&suffix){return gateName(suffix)+L".learning-v2";}
struct CaptureEmitter::State {
 struct Packet {std::shared_ptr<LearningForgetRequest>forget;CaptureHeader header;std::wstring text;CaptureContextWire source;std::optional<DecisionCapture>decision;DecisionLink link;size_t cost=0;};
 std::shared_ptr<const CaptureContextWire> hostSource;
 std::wstring suffix,pipe,gate;std::mutex lock;std::condition_variable wake;std::deque<Packet> pending;size_t pendingBytes=0;std::atomic<bool>stopping{false};std::atomic<uint64_t>lost{0};bool started=false;
 explicit State(std::wstring name):suffix(std::move(name)){}
 bool diagnosticsEnabled()const noexcept;
 void emit(std::wstring_view,HWND,const std::array<unsigned char,16>&,const std::array<unsigned char,16>&,bool,uint32_t,uint32_t,bool,bool,const DecisionCapture*,const DecisionLink*)noexcept;
 bool emitLearning(std::wstring_view,std::wstring_view,HWND,uint32_t,LearningCapability*)noexcept;
 void run()noexcept;
};
CaptureEmitter::CaptureEmitter(std::wstring name):state(std::make_shared<State>(std::move(name))){}
CaptureEmitter::~CaptureEmitter(){state->stopping=true;state->wake.notify_one();}
void CaptureEmitter::start(){if(state->started)return;try{auto current=state;current->pipe=pipeName(current->suffix);current->gate=gateName(current->suffix);if(!current->pipe.empty()&&!current->gate.empty())current->started=private_input::BackgroundTask::start([current]{current->run();});}catch(...) {}}
bool CaptureEmitter::diagnosticsEnabled()const noexcept{return state->diagnosticsEnabled();}
void CaptureEmitter::emit(std::wstring_view text,HWND hwnd,const std::array<unsigned char,16>&session,const std::array<unsigned char,16>&editor,bool normal,uint32_t layout,uint32_t field,bool paste,bool diagnostic,const DecisionCapture*decision,const DecisionLink*link)noexcept{state->emit(text,hwnd,session,editor,normal,layout,field,paste,diagnostic,decision,link);}
bool CaptureEmitter::emitLearning(std::wstring_view reading,std::wstring_view text,HWND hwnd,uint32_t kind,LearningCapability*used)noexcept{return state->emitLearning(reading,text,hwnd,kind,used);}
bool CaptureEmitter::State::diagnosticsEnabled()const noexcept{if(gate.empty())return false;HANDLE cap=OpenFileMappingW(FILE_MAP_READ,FALSE,(gate+L".diagnostic-v1").c_str());if(!cap)return false;auto*v=static_cast<const DWORD*>(MapViewOfFile(cap,FILE_MAP_READ,0,0,sizeof(DWORD)));bool allowed=v&&*v==1;if(v)UnmapViewOfFile(v);CloseHandle(cap);return allowed;}
void CaptureEmitter::State::emit(std::wstring_view text,HWND hwnd,const std::array<unsigned char,16>&session,const std::array<unsigned char,16>&editor,bool normal,uint32_t layout,uint32_t field,bool paste,bool diagnostic,const DecisionCapture*decision,const DecisionLink*link)noexcept{if(stopping||!started)return;if(diagnostic&&!diagnosticsEnabled())return;if(!normal||(text.empty()&&!decision))return;try{if(gate.empty())return;auto mapping=OpenFileMappingW(FILE_MAP_READ,FALSE,gate.c_str());if(!mapping)return;auto state=reinterpret_cast<const CaptureGate*>(MapViewOfFile(mapping,FILE_MAP_READ,0,0,sizeof(CaptureGate)));uint64_t generation=state&&state->enabled?uint64_t(state->generation):0;if(state)UnmapViewOfFile(state);CloseHandle(mapping);if(!generation)return;size_t extra=0;if(decision){extra=decision->before.size()+decision->after.size()+16384;if(decision->before.size()>4096||decision->after.size()>4096||decision->preview.size()>5)return;}std::unique_lock<std::mutex>guard(lock,std::try_to_lock);if(!guard||pending.size()>=64||pendingBytes+extra+(text.size()>120000?0:text.size()*sizeof(wchar_t))>2*1024*1024){++lost;return;}Packet packet;packet.header.kind=diagnostic?9:paste?8:1;if(decision)packet.decision=*decision;if(link&&!link->empty()&&diagnosticsEnabled())packet.link=*link;auto original=std::atomic_load(&hostSource);if(original)packet.source=*original;packet.source.field=field<=6?field:0;packet.source.layout=layout<=2?layout:0;packet.header.generation=generation;packet.header.foreground=reinterpret_cast<uintptr_t>(hwnd);packet.header.observedTick=GetTickCount64();FILETIME stamp{};GetSystemTimeAsFileTime(&stamp);ULARGE_INTEGER stampValue{};stampValue.LowPart=stamp.dwLowDateTime;stampValue.HighPart=stamp.dwHighDateTime;packet.header.observedAt=(stampValue.QuadPart-116444736000000000ULL)/10000000ULL;packet.header.scope=1;packet.header.session=session;packet.header.editor=editor;if(text.size()>120000){if(paste)return;packet.header.kind=2;}else packet.text.assign(text);packet.header.utf16Count=uint32_t(packet.text.size());packet.cost=packet.text.size()*sizeof(wchar_t)+extra;pendingBytes+=packet.cost;pending.push_back(std::move(packet));guard.unlock();wake.notify_one();}catch(...){++lost;}}
bool CaptureEmitter::State::emitLearning(std::wstring_view reading,std::wstring_view text,HWND hwnd,uint32_t kind,LearningCapability*used)noexcept{if(used)*used={};if(stopping||!started)return false;if((kind!=3&&kind!=5&&kind!=6&&kind!=7&&kind!=12)||reading.empty()||text.empty()||reading.size()>128||text.size()>1024||gate.empty())return false;try{auto mapping=OpenFileMappingW(FILE_MAP_READ,FALSE,learningName(suffix).c_str());if(!mapping)return false;auto state=static_cast<const LearningMapping*>(MapViewOfFile(mapping,FILE_MAP_READ,0,0,sizeof(LearningMapping)));auto generation=state&&state->version==LearningMappingVersion&&state->enabled?state->generation:0;if(state)UnmapViewOfFile(state);CloseHandle(mapping);if(!generation)return false;std::array<unsigned char,16> intentToken{};
 {auto cap=OpenFileMappingW(FILE_MAP_READ,FALSE,(learningName(suffix)+LearningIntentGateSuffix).c_str());if(!cap){++lost;return false;}auto*v=static_cast<const LearningIntentGate*>(MapViewOfFile(cap,FILE_MAP_READ,0,0,sizeof(LearningIntentGate)));bool ready=false;if(v){auto revision=v->revision;MemoryBarrier();if(!(revision&1)&&v->magic==LearningIntentGateMagic&&v->version==1&&v->enabled){intentToken=v->token;MemoryBarrier();ready=v->revision==revision&&hasLearningIntentID(intentToken);}UnmapViewOfFile(v);}CloseHandle(cap);if(!ready){++lost;return false;}}
 {auto h=OpenFileMappingW(FILE_MAP_READ,FALSE,learningName(suffix).c_str());if(!h)return false;auto*v=static_cast<const LearningMapping*>(MapViewOfFile(h,FILE_MAP_READ,0,0,sizeof(LearningMapping)));bool same=v&&v->enabled&&v->version==LearningMappingVersion&&v->generation==generation;if(v)UnmapViewOfFile(v);CloseHandle(h);if(!same)return false;}
 std::unique_lock<std::mutex>guard(lock,std::try_to_lock);if(!guard||pending.size()>=64){++lost;return false;}Packet packet;packet.header.kind=kind;
 {GUID id{};if(FAILED(CoCreateGuid(&id))){++lost;return false;}packet.header.session={static_cast<unsigned char>(id.Data1>>24),static_cast<unsigned char>(id.Data1>>16),static_cast<unsigned char>(id.Data1>>8),static_cast<unsigned char>(id.Data1),static_cast<unsigned char>(id.Data2>>8),static_cast<unsigned char>(id.Data2),static_cast<unsigned char>(id.Data3>>8),static_cast<unsigned char>(id.Data3),id.Data4[0],id.Data4[1],id.Data4[2],id.Data4[3],id.Data4[4],id.Data4[5],id.Data4[6],id.Data4[7]};packet.header.editor=intentToken;FILETIME stamp{};GetSystemTimeAsFileTime(&stamp);ULARGE_INTEGER utc{};utc.LowPart=stamp.dwLowDateTime;utc.HighPart=stamp.dwHighDateTime;packet.header.observedAt=(utc.QuadPart-116444736000000000ULL)/10000000ULL;}
packet.header.scope=1;packet.header.generation=generation;packet.header.foreground=reinterpret_cast<uintptr_t>(hwnd);packet.header.observedTick=GetTickCount64();packet.text=std::wstring(reading)+wchar_t(31)+std::wstring(text);packet.header.utf16Count=uint32_t(packet.text.size());packet.cost=packet.text.size()*sizeof(wchar_t);pendingBytes+=packet.cost;pending.push_back(std::move(packet));if(used)*used={intentToken,generation};guard.unlock();wake.notify_one();return true;}catch(...) {return false;}}
std::shared_ptr<LearningForgetRequest> CaptureEmitter::makeForget(std::wstring reading,std::wstring text,LearningCapability capability)noexcept{
 try{if(!capability.generation||!hasLearningIntentID(capability.token)||reading.empty()||reading.size()>128||text.empty()||text.size()>1024)return {};GUID id{};if(FAILED(CoCreateGuid(&id)))return {};std::array<unsigned char,16>event{static_cast<unsigned char>(id.Data1>>24),static_cast<unsigned char>(id.Data1>>16),static_cast<unsigned char>(id.Data1>>8),static_cast<unsigned char>(id.Data1),static_cast<unsigned char>(id.Data2>>8),static_cast<unsigned char>(id.Data2),static_cast<unsigned char>(id.Data3>>8),static_cast<unsigned char>(id.Data3),id.Data4[0],id.Data4[1],id.Data4[2],id.Data4[3],id.Data4[4],id.Data4[5],id.Data4[6],id.Data4[7]};FILETIME stamp{};GetSystemTimeAsFileTime(&stamp);ULARGE_INTEGER utc{};utc.LowPart=stamp.dwLowDateTime;utc.HighPart=stamp.dwHighDateTime;return std::make_shared<LearningForgetRequest>(capability,event,(utc.QuadPart-116444736000000000ULL)/10000000ULL,std::move(reading),std::move(text));}catch(...){return {};}
}
bool CaptureEmitter::sendForget(const std::shared_ptr<LearningForgetRequest>&request)noexcept{
 if(!request)return false;if(request->inFlight.exchange(true))return true;auto delivery=request->delivery;
 try{if(state->stopping||!state->started){request->finish(LearningIntentStatus::Retry);return false;}
 // Immutable original capability and event survive every retry. A closed
 // publication gate cannot cause rebinding; the Worker checks current authority.
 std::unique_lock<std::mutex>guard(state->lock,std::try_to_lock);if(!guard||state->pending.size()>=64){request->finish(LearningIntentStatus::Retry);return false;}
 State::Packet p;p.forget=request;p.header.kind=12;p.header.scope=1;p.header.generation=request->capability.generation;p.header.editor=request->capability.token;p.header.session=request->event;p.header.observedAt=request->createdAt;p.header.observedTick=GetTickCount64();p.text=request->reading+wchar_t(31)+request->text;p.header.utf16Count=uint32_t(p.text.size());p.cost=p.text.size()*sizeof(wchar_t);auto cost=p.cost;delivery->complete=false;delivery->status=LearningIntentStatus::Retry;state->pending.push_back(std::move(p));state->pendingBytes+=cost;guard.unlock();state->wake.notify_one();return true;
 }catch(...){request->finish(LearningIntentStatus::Retry);return false;}
}
