void CaptureEmitter::State::run()noexcept{std::shared_ptr<LearningForgetRequest>active;try{std::atomic_store(&hostSource,std::make_shared<const CaptureContextWire>(sourceForCurrentHost(true)));auto name=pipe;if(name.empty())return;for(;;){Packet packet;{std::unique_lock<std::mutex>guard(lock);wake.wait_for(guard,std::chrono::milliseconds(250),[&]{return stopping||!pending.empty();});if(stopping&&pending.empty())return;if(pending.empty())continue;packet=std::move(pending.front());pendingBytes-=packet.cost;pending.pop_front();}active=packet.forget;if(stopping&&!packet.forget)continue;if(packet.decision&&!diagnosticsEnabled())continue;auto retryLearning=[&]{auto now=GetTickCount64();std::unique_lock<std::mutex>guard(lock);if((!stopping||packet.forget)&&now>=packet.header.observedTick&&now-packet.header.observedTick<=30000&&pending.size()<64){pendingBytes+=packet.cost;pending.push_back(std::move(packet));wake.wait_for(guard,std::chrono::milliseconds(25));}else{++lost;if(packet.forget)packet.forget->finish(LearningIntentStatus::Retry);}};
 // New evidence is serialized only on this bounded sending worker, never TSF.
 try{if(packet.decision){auto payload=packet.decision->json().dump();int count=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,payload.data(),int(payload.size()),nullptr,0);if(count<=0)throw JsonError("decision UTF8");packet.text.resize(count);MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,payload.data(),int(payload.size()),packet.text.data(),count);}else if(!packet.link.empty()&&diagnosticsEnabled()){HANDLE cap=OpenFileMappingW(FILE_MAP_READ,FALSE,(gate+L".decision-v1").c_str());bool supported=false;if(cap){auto*v=static_cast<const DWORD*>(MapViewOfFile(cap,FILE_MAP_READ,0,0,sizeof(DWORD)));supported=v&&*v==1;if(v)UnmapViewOfFile(v);CloseHandle(cap);}if(supported){int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,packet.text.data(),int(packet.text.size()),nullptr,0,nullptr,nullptr);if(n<=0)throw JsonError("output UTF16");std::string raw(n,'\0');WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,packet.text.data(),int(packet.text.size()),raw.data(),n,nullptr,nullptr);auto encoded=decisionOutputPacket(raw,packet.link.json(),supported,diagnosticsEnabled(),true);auto payload=std::move(encoded.text);int count=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,payload.data(),int(payload.size()),nullptr,0);if(count<=0)throw JsonError("output JSON");if(encoded.kind==11&&count<=120000){packet.text.resize(count);MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,payload.data(),int(payload.size()),packet.text.data(),count);packet.header.kind=11;}}}packet.header.utf16Count=uint32_t(packet.text.size());}catch(...){++lost;if(packet.forget)packet.forget->finish(LearningIntentStatus::Invalid);continue;}
 const bool learningIntent=(packet.header.kind==3||packet.header.kind==12)&&hasLearningIntentID(packet.header.session)&&hasLearningIntentID(packet.header.editor);HANDLE pipe=CreateFileW(name.c_str(),GENERIC_WRITE|(learningIntent?GENERIC_READ:0),0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr);if(pipe==INVALID_HANDLE_VALUE){if(learningIntent)retryLearning();else ++lost;continue;}bool metadata=packet.header.kind==11;if(packet.header.kind==8||packet.header.kind==9){HANDLE capability=OpenFileMappingW(FILE_MAP_READ,FALSE,(gate+(packet.header.kind==9?L".diagnostic-v1":L".paste-v1")).c_str());if(!capability){CloseHandle(pipe);continue;}auto*v=static_cast<const DWORD*>(MapViewOfFile(capability,FILE_MAP_READ,0,0,sizeof(DWORD)));bool okay=v&&*v==1;if(v)UnmapViewOfFile(v);CloseHandle(capability);if(!okay){CloseHandle(pipe);continue;}metadata=true;}if(packet.header.kind<=2){HANDLE cap=OpenFileMappingW(FILE_MAP_READ,FALSE,contextCapabilityName(suffix).c_str());if(cap){auto*v=static_cast<const DWORD*>(MapViewOfFile(cap,FILE_MAP_READ,0,0,sizeof(DWORD)));metadata=v&&*v==2;if(v)UnmapViewOfFile(v);CloseHandle(cap);}}packet.header.version=metadata?2:1;auto loss=lost.exchange(0);if(loss){CaptureHeader gap=packet.header;gap.kind=packet.header.kind==9?10:((packet.header.kind>=3&&packet.header.kind<=7)||packet.header.kind==12)?4:2;gap.utf16Count=0;gap.version=1;DWORD n=0;OVERLAPPED o{};o.hEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);BOOL ok=WriteFile(pipe,&gap,sizeof(gap),&n,&o);if(!ok&&GetLastError()==ERROR_IO_PENDING){if(WaitForSingleObject(o.hEvent,25)!=WAIT_OBJECT_0)CancelIoEx(pipe,&o);GetOverlappedResult(pipe,&o,&n,TRUE);}CloseHandle(o.hEvent);}std::string data(sizeof(packet.header)+packet.text.size()*sizeof(wchar_t)+(metadata?sizeof(CaptureContextWire):0),'\0');memcpy(data.data(),&packet.header,sizeof(packet.header));if(!packet.text.empty())memcpy(data.data()+sizeof(packet.header),packet.text.data(),packet.text.size()*sizeof(wchar_t));if(metadata)memcpy(data.data()+sizeof(packet.header)+packet.text.size()*sizeof(wchar_t),&packet.source,sizeof(packet.source));OVERLAPPED o{};o.hEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);DWORD n=0;BOOL ok=WriteFile(pipe,data.data(),DWORD(data.size()),&n,&o);if(!ok&&GetLastError()==ERROR_IO_PENDING){if(WaitForSingleObject(o.hEvent,25)!=WAIT_OBJECT_0)CancelIoEx(pipe,&o);ok=GetOverlappedResult(pipe,&o,&n,TRUE);}bool retry=learningIntent&&(!ok||n!=data.size());if(ok&&n==data.size()&&learningIntent){LearningIntentAck ack;OVERLAPPED read{};read.hEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);DWORD got=0;BOOL received=ReadFile(pipe,&ack,sizeof(ack),&got,&read);if(!received&&GetLastError()==ERROR_IO_PENDING){if(WaitForSingleObject(read.hEvent,packet.forget?250:25)!=WAIT_OBJECT_0)CancelIoEx(pipe,&read);received=GetOverlappedResult(pipe,&read,&got,TRUE);}CloseHandle(read.hEvent);if(received&&got==sizeof(ack)&&validLearningIntentAck(ack,packet.header.session)){retry=ack.status==LearningIntentStatus::Retry||ack.status==LearningIntentStatus::Quota;if(!learningDurableAccepted(ack.status)&&!retry)++lost;if(packet.forget&&!retry)packet.forget->finish(ack.status);}else retry=true;}else if(!learningIntent&&(!ok||n!=data.size()))++lost;CloseHandle(o.hEvent);CloseHandle(pipe);
 if(retry)retryLearning();
}}catch(...){stopping=true;if(active&&active->inFlight.load())active->finish(LearningIntentStatus::Retry);try{std::lock_guard<std::mutex>guard(lock);for(auto&p:pending)if(p.forget)p.forget->finish(LearningIntentStatus::Retry);pending.clear();pendingBytes=0;}catch(...) {}}}
